import { io } from 'socket.io-client'

// Аутентификация: Bearer-токен. Traefik forwardAuth валидирует его и вклеивает
// X-User-Id/X-User-Name в handshake — сервер берёт identity оттуда, userId клиент
// не передаёт. Заголовки в браузере проходят только через polling-транспорт,
// поэтому polling ставим ПЕРВЫМ (дальше идёт upgrade на websocket).
const socket = io('https://realtimemap.ru/chats', {
  transports: ['polling', 'websocket'],
  withCredentials: true,
  extraHeaders: { Authorization: `Bearer ${token}` },
})

socket.on('connect', () => console.log('connected', socket.id))

// Одно соединение — события из ВСЕХ чатов пользователя. Роутим по chatId.
socket.on('message.new', (msg) => {
  // msg = { id, type, senderId, content, clientMessageId, createdAt, chatId, sender:{ id, username, avatar } }
  // Своё эхо (msg.senderId === myUserId): матчим по clientMessageId и заменяем temp id -> msg.id.
  appendMessageToChat(msg.chatId, msg)
})

socket.on('connect_error', (err) => {
  // токен протух / не прошёл auth
  console.error('socket auth failed:', err.message)
})

// Собеседник продвинул курсор прочтения — рисуем галочки и/или обнуляем unread.
socket.on('chat.read', (e) => {
  // e = { chatId, userId, lastReadMessageId }
  if (e.userId === myUserId) {
    // эхо с другого моего устройства — синхронизируем локальный unread
    resetUnread(e.chatId, e.lastReadMessageId)
  } else {
    // собеседник прочитал мои сообщения до lastReadMessageId
    markMessagesRead(e.chatId, e.userId, e.lastReadMessageId)
  }
})

// Отправка отметки о прочтении — троттлить (≤ 1 раз / 1–2с), только при новых
// увиденных сообщениях или возврате фокуса на чат.
async function markChatRead(chatId) {
  await fetch(`/api/v2/chats/${chatId}/read`, { method: 'POST', headers: { Authorization: `Bearer ${token}` } })
}

// Локальное состояние присутствия, собираемое из событий сервера.
const onlineUsers = new Set()

// Снимок — приходит один раз сразу после connect. Полностью заменяет состояние.
socket.on('presence.snapshot', (e) => {
  // e = { online: [2, 5, 9] }
  onlineUsers.clear()
  e.online.forEach((id) => onlineUsers.add(id))
  renderOnlineBadges(onlineUsers)
})

// На разрыве соединения накопленное состояние недостоверно — сбрасываем.
// После реконнекта придёт свежий presence.snapshot.
socket.on('disconnect', () => {
  onlineUsers.clear()
  renderOnlineBadges(onlineUsers)
})

socket.on('presence.online', (e) => {
  // e = { userId, online: true, at }
  onlineUsers.add(e.userId)
  renderOnlineBadges(onlineUsers)
})

// Один обработчик на оба события — различаем по полю online.
function handlePresence(e) {
  if (e.online) onlineUsers.add(e.userId)
  else onlineUsers.delete(e.userId)
  renderOnlineBadges(onlineUsers)
}
socket.on('presence.online', handlePresence)
socket.on('presence.offline', handlePresence)

socket.on('presence.offline', (e) => {
  // e = { userId, online: false, at }
  onlineUsers.delete(e.userId)
  // Ушедший в офлайн не может продолжать печатать — гасим и индикатор набора.
  typingUsers.delete(e.userId)
  renderOnlineBadges(onlineUsers)
  renderTypingIndicator(typingUsers)
})

// userId -> username тех, кто печатает. Ключ по userId: в групповом чате
// одновременно печатать могут несколько человек.
const typingUsers = new Map()

socket.on('chat.typing', (e) => {
  // e = { chatId, userId, username, isTyping }
  if (e.userId === myUserId) return // эхо с другого моего устройства

  if (e.isTyping) typingUsers.set(e.userId, e.username)
  else typingUsers.delete(e.userId)

  renderTypingIndicator(e.chatId, typingUsers)
})

// Отдельный таймер гашения на клиенте НЕ нужен: сервер сам пришлёт
// isTyping=false по таймауту или при разрыве соединения собеседника.

let typingSent = false
let stopTimer = null

input.addEventListener('input', () => {
  // Поле очистили — набор прекращён, гасим индикатор сразу.
  if (!input.value.trim()) return sendTypingStop()

  // Throttle: не чаще одного start в 2 секунды.
  if (!typingSent) {
    socket.emit('typing.start', { chatId })
    typingSent = true
    setTimeout(() => { typingSent = false }, 2000)
  }

  // Пользователь замер, не отправив сообщение — гасим сами, не дожидаясь
  // серверного автосброса (~6с).
  clearTimeout(stopTimer)
  stopTimer = setTimeout(sendTypingStop, 3000)
})

function sendTypingStop() {
  clearTimeout(stopTimer)
  typingSent = false
  socket.emit('typing.stop', { chatId })
}

// После успешной отправки сообщения набор окончен — гасим индикатор сразу,
// не дожидаясь серверного автосброса.
async function sendMessage(chatId, content) {
  await fetch(`/api/v2/chats/${chatId}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify({ content }),
  })

  socket.emit('typing.stop', { chatId })
}

// Также стоит слать при уходе из чата / потере фокуса.
function onLeaveChat(chatId) {
  socket.emit('typing.stop', { chatId })
}
